describe("normalizeLineHeightMultiplier", () => {
    it("recovers legacy mis-scaled values", () => {
        expect(normalizeLineHeightMultiplier(100)).toBe(1);
        expect(normalizeLineHeightMultiplier(90)).toBe(0.9);
    });
    it("accepts sane multipliers", () => {
        expect(normalizeLineHeightMultiplier(1.2)).toBe(1.2);
        expect(normalizeLineHeightMultiplier(0.9)).toBe(0.9);
    });
    it("rejects out-of-range values", () => {
        expect(normalizeLineHeightMultiplier(5)).toBeUndefined();
        expect(normalizeLineHeightMultiplier(0.5)).toBeUndefined();
    });
});
