describe("resolveSlideTextBackground", () => {
    const baseSlide = () => ({
        index: 1,
        title: "T",
        texts: [],
        blocks: [],
        tables: [],
        chartCount: 0,
        charts: [],
        elements: [],
        slideWidth: 1000,
        slideHeight: 750,
        images: []
    });
    it("uses darkest gradient stop on dark slides", () => {
        const slide = baseSlide();
        slide.backgroundGradient = "linear-gradient(90deg, #ffffff 0%, #0f172a 100%)";
        expect(resolveSlideTextBackground(slide)).toBe("#0f172a");
    });
    it("uses large dark shape fill when slide bg is unset", () => {
        const slide = baseSlide();
        slide.elements = [
            {
                kind: "shape",
                x: 0,
                y: 0,
                w: 900,
                h: 700,
                zIndex: 0,
                fillColor: "#1e293b",
                shapeType: "rect"
            }
        ];
        expect(resolveSlideTextBackground(slide)).toBe("#1e293b");
    });
    it("prefers local light shape for text on colored boxes", () => {
        const slide = baseSlide();
        slide.backgroundColor = "#0f172a";
        slide.elements = [
            {
                kind: "shape",
                x: 0,
                y: 0,
                w: 900,
                h: 700,
                zIndex: 0,
                fillColor: "#0f172a",
                shapeType: "rect"
            },
            {
                kind: "shape",
                x: 50,
                y: 50,
                w: 200,
                h: 60,
                zIndex: 1,
                fillColor: "#f97316",
                shapeType: "rect"
            },
            {
                kind: "text",
                x: 60,
                y: 60,
                w: 180,
                h: 40,
                zIndex: 2,
                text: "SOLUTION"
            }
        ];
        const textEl = slide.elements[2];
        expect(resolveElementTextBackground(slide, textEl)).toBe("#f97316");
    });
});
